<template><view class="page"><text class="title">隐私与授权</text><text class="sub">管理本机偏好。服务端家庭权限模型尚未开放配置。</text><view class="card"><view v-for="item in items" :key="item.key" class="row"><view><text class="name">{{item.name}}</text><text class="desc">{{item.desc}}</text></view><switch :checked="item.enabled" color="#2fa99a" @change="onChange(item,$event)"/></view></view><button class="save" @tap="save">保存本机偏好</button><view class="tip">健康、位置与设备数据只有在获得实际来源和相应授权后才会进入系统；本页不会自动生成任何个人数据。</view></view></template><script>export default{data(){return{items:[{key:'health',name:'健康数据展示',desc:'允许本机展示已授权的健康记录',enabled:true},{key:'location',name:'位置数据展示',desc:'仅在接入真实位置来源后生效',enabled:false},{key:'device',name:'设备数据展示',desc:'仅显示已绑定设备实际上报的数据',enabled:true}]}},onLoad(){const saved=uni.getStorageSync('privacy_settings');if(Array.isArray(saved))this.items=this.items.map(i=>({...i,enabled:saved.find(x=>x.key===i.key)?.enabled??i.enabled}))},methods:{onChange(item,e){item.enabled=e.detail.value},save(){uni.setStorageSync('privacy_settings',this.items.map(({key,enabled})=>({key,enabled})));uni.showToast({title:'已保存',icon:'success'})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#fff9f2}.title{display:block;font-size:40rpx;font-weight:900;color:#493a33}.sub{display:block;margin:10rpx 0 28rpx;color:#8b786d;line-height:1.6}.card{padding:0 24rpx 24rpx;background:#fff;border-radius:28rpx}.row{min-height:116rpx;display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid #f0e7df}.name,.desc{display:block}.name{font-size:25rpx;font-weight:800}.desc{margin-top:6rpx;color:#928077;font-size:19rpx}.save{margin-top:24rpx;background:#2fa99a;color:#fff;border-radius:20rpx}.tip{margin-top:24rpx;padding:24rpx;border-radius:22rpx;background:#eff8f5;color:#637d76;font-size:21rpx;line-height:1.7}</style>